import { useState } from "react";

function Form() {
  const [ten, setTen] = useState("");
  const [chao, setChao] = useState("");
  const gui = (e) => {
    e.preventDefault();
    setChao("Xin chao, " + ten);
  };
  return (
    <form onSubmit={gui}>
      <input value={ten} onChange={(e) => setTen(e.target.value)} />
      <button>Gui</button>
      <p>{chao}</p>
    </form>
  );
}

export default Form;
